def save():
 def clean(v,financial=False):
  if isinstance(v,str):
   v=v.replace(r'\$',r'\text{USD}\,')
   return v
  if isinstance(v,list):return [clean(a,financial) for a in v]
  if isinstance(v,dict):return {k:clean(a,financial) for k,a in v.items()}
  return v
 for k in Q:Q[k]=clean(Q[k],Q[k]['subtopic']=='Financial and growth models')
 dest=BASE/'number-algebra.json';tmp=dest.with_suffix('.tmp')
 with open(tmp,'w') as f:json.dump([Q[k] for k in sorted(Q)],f,ensure_ascii=False,indent=2);f.flush();os.fsync(f.fileno())
 os.replace(tmp,dest)
save()
