add(126,'Parameters giving no intersection','Systems of linear equations',r'Three planes satisfy $$x+2y-2z=5,\quad3x+5y-4z=11,\quad4x+6y+az=b.$$ Find all a,b for which they have no common point.',p('','',5,('M1','Subtract twice equation 1 from twice equation 2.'),('A1',r'$4x+6y-4z=12$.'),('M1',r'Subtract this from equation 3 to obtain $(a+4)z=b-12$.'),('R1','Inconsistency occurs precisely when the z coefficient is zero but the right side is non-zero.'),('A1',r'$a=-4$, $b\ne12$.')))
