add(133,'Arranging volunteers with repeated categories','Counting principles','Twelve booths form three rows of four. Volunteers consist of 4 indistinguishable red-shirt volunteers, 4 indistinguishable blue-shirt volunteers, 2 indistinguishable green-shirt volunteers and two distinct volunteers, Asha and Ben.',p('a','Find the number of assignments when Asha and Ben are both in the front row.',3,('M1',r'Place the two named volunteers in $4\times3=12$ ways.'),('M1',r'Fill the remaining booths in $10!/(4!4!2!)$ ways.'),('A1',f'${12*ways}$.')),p('b','Now both must be in the middle row and non-adjacent, or both in the back row with at least two booths between them. Find the number of assignments.',3,('A1',r'The middle row allows $4\times3-2(3)=6$ ordered pairs.'),('A1','The back row allows 2 ordered pairs: positions 1 and 4.'),('A1',f'$({6}+{2})\\frac{{10!}}{{4!4!2!}}={8*ways}$.')))
