add(141,'Comparing geometric and logarithmic sums','Sequences and series',r'A geometric sequence has positive ratio r, first term 64 and sum of the first four terms 175. Let $G_n$ be its nth partial sum. An arithmetic sequence begins $\log_{10}80,\log_{10}40,\log_{10}20,\ldots$; let its nth partial sum be $A_n$.',p('a','Find r and a formula for $G_n$.',3,('M1',r'$64(1+r+r^2+r^3)=175$.'),('A1',r'$r=3/4$ (unique for positive r).'),('A1',r'$G_n=256[1-(3/4)^n]$.')),p('b','Find the arithmetic difference in logarithmic form.',2,('M1',r'$d=\log_{10}(40/80)$.'),('A1',r'$d=-\log_{10}2$.')),p('c',r'Show that $A_n=\log_{10}(5^n2^{(9n-n^2)/2})$.',5,('M1',r'$A_n=\frac n2[2\log_{10}80-(n-1)\log_{10}2]$.'),('A1',r'$\log_{10}80=\log_{10}5+4\log_{10}2$.'),('A1',r'$A_n=n\log_{10}5+\frac{9n-n^2}2\log_{10}2$.'),('M1','Apply the power and product laws.'),('A1',r'$A_n=\log_{10}(5^n2^{(9n-n^2)/2})$.')),p('d',r'Find the greatest positive integer n for which $|G_n|>|A_n|$.',3,('M1','Compare the two expressions numerically near the final crossing.'),('A1',f'At n={Nmax}, $G_n\\approx{F(G(Nmax))}$ and $|A_n|={F(abs(AS(Nmax)))}$; at n={Nmax+1}, $G_n\\approx{F(G(Nmax+1))}$ and $|A_n|={F(abs(AS(Nmax+1)))}$.'),('A1',f'$n={Nmax}$. Beyond this crossing, $|A_n|$ increases quadratically whereas $G_n<256$, so no later n qualifies.')))
