add(144,'Comparing two coefficients in a high-power expansion','Binomial theorem',r'In $(x^2+2x^6/q)^{10}$, where $q\ne0$, the coefficient of $x^{40}$ is six times that of $x^{36}$. Find q.',p('','',7,('M1',r'The general term is $\binom{10}j2^jq^{-j}x^{20+4j}$.'),('A1',r'$x^{40}$ uses j=5; $x^{36}$ uses j=4.'),('A1',r'The coefficients are $252\cdot32/q^5$ and $210\cdot16/q^4$.'),('M1','Set the former equal to six times the latter.'),('A1',r'$252\cdot32=6(210)(16)q$.'),('M1','Divide by the non-zero numerical factor.'),('A1',r'$q=2/5$.')))
