add(149,'Choosing the convergent geometric sequence','Sequences and series',r'The first three terms of a geometric sequence are $k-5,6,k+4$, where k is an integer.',p('a',r'Find an expression for r and show that $k^2-k-56=0$.',5,('M1',r'$r=6/(k-5)$.'),('A1',r'Also $r=(k+4)/6$.'),('M1','Equate the two ratios.'),('A1',r'$(k-5)(k+4)=36$.'),('A1',r'$k^2-k-56=0$.')),p('b','Find all possible k and their corresponding r.',5,('M1',r'$(k-8)(k+7)=0$.'),('A1',r'$k=8$ or $k=-7$.'),('M1','Substitute each into $r=6/(k-5)$.'),('A1',r'$k=8$ gives $r=2$.'),('A1',r'$k=-7$ gives $r=-1/2$.')),p('c','The sequence has a finite sum to infinity. Identify it and find the sum.',5,('R1',r'Convergence requires $|r|<1$.'),('A1',r'Choose $r=-1/2$, hence $k=-7$.'),('A1',r'The first term is $-12$.'),('M1',r'$S_\infty=-12/(1+1/2)$.'),('A1',r'$S_\infty=-8$.')))
