add(161,'Combining compound growth and contributions','Financial and growth models','A parent invests USD 22 000 for six years at 6% nominal annually, compounded monthly, toward a USD 45 000 target. A relative earns USD 42 000 annually and offers an end-of-year contribution of one fifth of this income in year 1, then halves each subsequent contribution. Contributions earn no interest.',p('a','Show that the investment alone is insufficient.',2,('M1',r'$V=22000(1.005)^{72}$.'),('A1',f'$V={D(balance)}<45000$, so it is insufficient.')),p('b','Find the minimum whole-dollar initial investment that would reach the target in six years.',3,('M1',r'$P(1.005)^{72}\ge45000$.'),('A1',f'$P\\ge {45000/1.005**72:.4f}$.'),('A1',f'USD {math.ceil(45000/1.005**72):,}; round upward to ensure the target is met.')),p('c','Show that six years of contributions together with the original investment exceed the target.',4,('A1','First contribution is USD 8400; ratio is 1/2.'),('M1',r'$C_6=8400(1-0.5^6)/(1-0.5)$.'),('A1',f'$C_6={D(8400*(1-.5**6)/.5)}$.'),('R1',f'Total ${D(balance+8400*(1-.5**6)/.5)}>45000$.')),p('d','The relative stops once cumulative contributions cover the investment’s projected shortfall at the end of year 6. Find after how many contributions they stop.',4,('M1',f'The fixed projected shortfall is ${D(deficit)}$.'),('A1',r'Solve $16800(1-0.5^j)\ge45000-22000(1.005)^{72}$.'),('M1','Check consecutive integers at the boundary.'),('A1',f'After {stop-1} contributions: {D(8400*(1-.5**(stop-1))/.5)}; after {stop}: {D(8400*(1-.5**stop)/.5)}. Thus {stop} contributions.')))
