add(169,'Arranging books in a block','Counting principles','Ten distinct books consist of 4 biographies and 6 novels. Find the number of shelf arrangements under each condition.',p('a','The biographies are together.',2,('M1','Treat the biographies as one block: 7 objects, with 4! internal orders.'),('A1',f'$7!4!={math.factorial(7)*24}$.')),p('b','The biographies are together at either end.',2,('M1','Choose the end in 2 ways; arrange biographies and novels internally.'),('A1',f'$2(4!)(6!)={2*24*math.factorial(6)}$.')),p('c','The biographies are together, but not at an end.',2,('M1','Subtract the end cases from part (a).'),('A1',f'$7!4!-2(4!)(6!)={math.factorial(7)*24-2*24*math.factorial(6)}$.')))
