add(171,'An arithmetic sum as a quadratic function','Sequences and series',r'An arithmetic sequence satisfies $u_6=\ln3$ and $u_8=5\ln3$. Define $f(x)=(x^2-10x)\ln3$ for real x and $g(x)=(8-2x)\ln3$.',p('a',r'Find d and $u_1$, and show that $S_n=(n^2-10n)\ln3$.',5,('M1',r'$2d=4\ln3$.'),('A1',r'$d=2\ln3$.'),('A1',r'$u_1=\ln3-5(2\ln3)=-9\ln3$.'),('M1',r'$S_n=\frac n2[-18+2(n-1)]\ln3$.'),('A1',r'$S_n=(n^2-10n)\ln3$.')),p('b','State the axis of symmetry of f, describe its sketch with intercepts, and find the minimum value of $S_n$.',5,('A1',r'The axis is x=5.'),('A1',r'The x-intercepts are (0,0) and (10,0).'),('R1',r'The graph opens upwards because $\ln3>0$.'),('A1',r'The vertex is $(5,-25\ln3)$.'),('A1',r'The minimum discrete sum is $S_5=-25\ln3$.')),p('c','Solve f(x)=g(x), then f(x)<g(x), and hence find all positive integers n with $S_n<g(n)$.',5,('M1',r'$x^2-8x-8=0$.'),('A1',r'$x=4\pm2\sqrt6$.'),('R1','The upward-opening quadratic is negative between its roots.'),('A1',r'$4-2\sqrt6<x<4+2\sqrt6$.'),('A1',r'$n=1,2,\ldots,8$.')))
