add(175,'A relation between quartic coefficients','Complex numbers',r'The real equation $2z^4+az^3+bz^2+cz+d=0$ has roots $\log_3 18$ and $i\sqrt7$. The sum of all roots is $5+\log_3 2$. Show that $21a=-(d+126)$.',p('','',6,('A1',r'$-i\sqrt7$ is also a root.'),('M1',r'Write $\log_318=2+\log_32$; the fourth root is 3.'),('A1',r'By the sum formula, $a=-2(5+\log_32)$.'),('M1','Use the product formula with leading coefficient 2.'),('A1',r'$d=2\cdot7\cdot3(2+\log_32)=42(2+\log_32)$.'),('A1',r'$21a=-42(5+\log_32)=-(d+126)$.')))
def linear_exp_proof(k,shift,lam,extended=False):
 t=s.symbols('t');f=(x+shift)*s.exp(lam*x);der=s.diff(f,x)
 parts=[p('a',r"Find $f'(x)$.",2,('M1','Use the product rule.'),('A1',f'$f\prime(x)={L(s.factor(der))}$.'))]
 proofmarks=7
 parts.append(p('b',f'Prove by induction that $f^{{(n)}}(x)=[n({lam})^{{n-1}}+({lam})^n({L(x+shift)})]e^{{{L(lam*x)}}}$ for every positive integer n.',proofmarks,('A1','The n=1 case is the derivative in part (a).'),('M1','Assume the result for n=k.'),('M1','Differentiate the assumed expression using the product rule.'),('A1',f'$f^{{(k+1)}}=[({lam})^k+({L(lam)})(k({lam})^{{k-1}}+({lam})^k({L(x+shift)}))]e^{{{L(lam*x)}}}$.'),('A1',f'The bracket simplifies to $(k+1)({lam})^k+({lam})^{{k+1}}({L(x+shift)})$.'),('R1','This is precisely the proposed formula at k+1.'),('R1','The base case and induction step prove the formula.')))
 if extended:
  stat=-s.Rational(1,lam)-shift;infl=-s.Rational(2,lam)-shift;sv=s.simplify(f.subs(x,stat));iv=s.simplify(f.subs(x,infl));nature='minimum' if lam>0 else 'maximum'
  parts.append(p('c','Find and classify every stationary point.',5,('M1',f'$f\prime=e^{{{L(lam*x)}}}[1+({L(lam)})({L(x+shift)})]=0$.'),('A1',f'$x={L(stat)}$.'),('A1',f'The point is $({L(stat)},{L(sv)})$.'),('M1',f'$f\prime\prime=e^{{{L(lam*x)}}}[2({lam})+({lam})^2({L(x+shift)})]$; at the stationary point its sign is the sign of {lam}.'),('R1',f'This point is a {nature}; there are no others.')))
  parts.append(p('d','Find and justify every point of inflection.',5,('M1',f'Solve $2({lam})+({lam})^2({L(x+shift)})=0$.'),('A1',f'$x={L(infl)}$.'),('A1',f'The point is $({L(infl)},{L(iv)})$.'),('R1','The linear factor in the second derivative has a simple root and changes sign there.'),('R1','The exponential factor is positive, so concavity changes and the point is an inflection.')))
  mm=REF[k-1]['marks']-19
  parts.append(p('e','Sketch f, clearly showing the intercepts, stationary point, inflection point and end behaviour.',mm,('A1',f'Intercepts: $({-shift},0)$ and $(0,{shift})$.'),('A1',f'Plot the stationary and inflection points from (c),(d), with the correct {nature} and concavity change.'),('A'+str(mm-2),r'The curve tends to $0^-$ as $x\to-\infty$ and to $+\infty$ as $x\to+\infty$.' if lam>0 else r'The curve tends to $-\infty$ as $x\to-\infty$ and to $0^+$ as $x\to+\infty$.')))
 add(k,'Induction for repeated differentiation','Proof and mathematical induction',f'Let $f(x)=({L(x+shift)})e^{{{L(lam*x)}}}$, for real x.',*parts)
 ck(all(s.simplify(s.diff(f,x,j)-(j*lam**(j-1)+lam**j*(x+shift))*s.exp(lam*x))==0 for j in range(1,8)),f'Q{k}: derivative formula n=1..7')
linear_exp_proof(176,2,-3)
