add(178,'Divisibility of a cubic expression','Proof and mathematical induction',r'Prove by induction that $n(n^2+11)$ is divisible by 6 for all positive integers n.',p('','',6,('A1',r'At n=1, the expression is 12.'),('M1','Assume F(k) is divisible by 6.'),('M1',r'$F(k+1)-F(k)=3k^2+3k+12$.'),('A1',r'$=3k(k+1)+12$.'),('R1','k(k+1) is even, so both terms are divisible by 6.'),('R1','Thus F(k+1) is divisible by 6 and induction completes the proof.')))
add(179,'Linking arithmetic and geometric logarithms','Sequences and series',r'A geometric sequence begins $4\log_2x,3\log_2x,\ldots$, where $x>0$, $x\ne1$. An arithmetic sequence begins $\log_2x,\log_2(x/2),\log_2(x/4),\ldots$.',p('a','Find the geometric ratio.',2,('M1','Divide the second term by the first.'),('A1',r'$r=3/4$.')),p('b',r'Show that the geometric sum to infinity is $16\log_2x$.',3,('R1',r'$|r|=3/4<1$.'),('M1',r'$S_\infty=4\log_2x/(1-3/4)$.'),('A1',r'$S_\infty=16\log_2x$.')),p('c','Find the arithmetic difference.',3,('M1',r'$d=\log_2(x/2)-\log_2x$.'),('A1',r'$d=\log_2(1/2)$.'),('A1',r'$d=-1$.')),p('d',r'Show that the arithmetic sum $S_8=8\log_2x-28$.',3,('M1',r'$S_8=\frac82[2\log_2x+7(-1)]$.'),('A1',r'$=4(2\log_2x-7)$.'),('A1',r'$=8\log_2x-28$.')),p('e','Find x if this arithmetic sum is one quarter of the geometric sum to infinity.',3,('M1',r'$8\log_2x-28=4\log_2x$.'),('A1',r'$\log_2x=7$.'),('A1',r'$x=128$.')))
add(180,'Solving a trigonometric logarithm equation','Exponents and logarithms','',p('a',r'Show that $\log_3\sqrt{4-\cos2x}=\log_9(4-\cos2x)$.',3,('M1','Use the power law on the square root.'),('A1',r'$\log_3\sqrt A=\frac12\log_3A=\log_9A$.'),('R1',r'$A=4-\cos2x\ge3>0$, so the operations are valid.')),p('b',r'Solve $\log_9(2\sin x)+\frac12=\log_3\sqrt{4-\cos2x}$ for $0<x<\pi/2$.',5,('M1',r'Combine logs: $\log_9(6\sin x)=\log_9(4-\cos2x)$.'),('A1',r'$6\sin x=3+2\sin^2x$.'),('M1',r'Let $u=\sin x$; $2u^2-6u+3=0$.'),('A1',r'$u=(3\pm\sqrt3)/2$; only the minus sign is in (0,1).'),('A1',r'$x=\arcsin((3-\sqrt3)/2)$.')))
add(181,'Arrangements of two groups','Counting principles','Three boys and four girls, all distinct, stand in one row.',p('a','Find the number of arrangements in which each group forms a single block.',1,('A1',r'$2(3!)(4!)=288$.')),p('b','Find the number in which the boys stand together.',1,('A1',r'$5!3!=720$.')),p('c','Find the number in which boys and girls alternate.',1,('A1',r'Only G B G B G B G is possible: $4!3!=144$.')),p('d','Find the number in which no two boys are adjacent, with no further restriction on the girls.',2,('M1','Arrange girls, select 3 of their 5 gaps, then arrange boys.'),('A1',r'$4!\binom53 3!=1440$.')))
add(182,'A dependent system with one parameter','Systems of linear equations',r'Consider $$x+y+z=-2,\quad4x+2y+z=1,\quad9x+3y=p.$$ ',p('a','Show that the system never has a unique solution.',4,('M1','Subtract equation 1 from equation 2.'),('A1',r'$3x+y=3$.'),('M1','Multiply by 3: $9x+3y=9$.'),('R1','The third coefficient row is dependent on the first two. It is either inconsistent or redundant, so uniqueness is impossible.')),p('b','Find p for consistency and give the general solution then.',4,('A1',r'$p=9$.'),('M1',r'Let $z=t$ and solve $x+y=-2-t$, $3x+y=3$.'),('A1',r'$x=(5+t)/2$.'),('A1',r'$y=(-9-3t)/2$, $z=t$, $t\in\mathbb R$.')),note='The printed reference omits later subparts. Added the natural parameter/solution-family continuation of its dependent-plane task; row dependence checked explicitly.')
add(183,'Cube roots and a cosine identity','Complex numbers',r'Consider $z^3=-27/2+(27\sqrt3/2)i$.',p('a','Express the right-hand side in exponential form with principal argument.',5,('M1',r'Modulus is $\sqrt{(27/2)^2+(27\sqrt3/2)^2}$.'),('A1',r'This is 27.'),('R1','The point lies in quadrant II.'),('A1',r'The argument is $2\pi/3$.'),('A1',r'$27e^{2\pi i/3}$.')),p('b','Find all three roots in exponential form with principal arguments.',5,('M1',r'Each root has modulus $27^{1/3}=3$.'),('M1',r'Arguments are $2\pi/9+2k\pi/3$, k=0,1,2.'),('A1',r'$3e^{2\pi i/9}$.'),('A1',r'$3e^{8\pi i/9}$.'),('A1',r'$3e^{-4\pi i/9}$.')),p('c','Find the exact area of the triangle formed by these roots.',4,('R1','The equal angular gaps are $2\pi/3$, so the triangle is equilateral.'),('M1',r'Use three centre triangles, each area $\frac12(3)(3)\sin(2\pi/3)$.'),('A1',r'Total area $=\frac{27}2\frac{\sqrt3}2$.'),('A1',r'$27\sqrt3/4$.')),p('d',r'Hence show that $\cos(2\pi/9)+\cos(4\pi/9)+\cos(8\pi/9)=0$.',4,('M1','The coefficient of $z^2$ is zero, so the sum of roots is zero.'),('A1',r'Take real parts: $3[\cos(2\pi/9)+\cos(8\pi/9)+\cos(-4\pi/9)]=0$.'),('A1',r'Cosine is even, so $\cos(-4\pi/9)=\cos(4\pi/9)$.'),('R1','Divide by 3 to obtain the identity.')))
add(184,'Summing multiples and an arithmetic bound','Sequences and series','Consider all integers between 30 and 350 inclusive that are divisible by 11.',p('a','Find their sum.',2,('M1',r'Terms run from 33 to 341, giving 29 terms; use $29(33+341)/2$.'),('A1','5423.')),p('b','Write the sum in sigma notation.',2,('A1','The multiplier of 11 runs from 3 to 31.'),('A1',r'$\sum_{k=3}^{31}11k$.')),p('c','An arithmetic sequence starts at -600 with difference 10. Find the greatest n for which its partial sum is negative.',2,('M1',r'$S_n=\frac n2[-1200+10(n-1)]=5n(n-121)<0$.'),('A1',r'$n=120$.')))
add(185,'A trigonometric geometric series','Sequences and series',r'The first three terms are $3\cos x,3\sin2x,12\sin^2x\cos x$, where $-\pi/2<x<\pi/2$ and $x\ne0$.',p('a','Find the common ratio.',1,('A1',r'$r=2\sin x$.')),p('b','Find all x for which the infinite series converges.',3,('M1',r'$|2\sin x|<1$.'),('A1',r'$-1/2<\sin x<1/2$.'),('A1',r'$-\pi/6<x<\pi/6$, excluding x=0 as stipulated.')),p('c',r'For $x=\arcsin(1/4)$, find the exact sum to infinity.',3,('A1',r'$r=1/2$ and $\cos x=\sqrt{15}/4$.'),('M1',r'$S_\infty=(3\sqrt{15}/4)/(1-1/2)$.'),('A1',r'$3\sqrt{15}/2$.')))
add(186,'A conjugate pair in a cubic','Complex numbers',r'One root of $3z^3+az^2+bz-156=0$, with real a,b, is $2+3i$.',p('a','Find the remaining roots.',4,('A1',r'$2-3i$ is a root.'),('M1',r'The product of all roots is $156/3=52$.'),('A1',r'The conjugate pair has product 13.'),('A1',r'The remaining root is 4.')),p('b','Find a,b.',3,('M1',r'$3(z-4)(z^2-4z+13)$.'),('A1',r'$=3z^3-24z^2+87z-156$.'),('A1',r'$a=-24$, $b=87$.')))
add(187,'A coefficient in a product of expansions','Binomial theorem',r'For a positive integer n, $(4+nx)^2(1+x/4)^n=16+96x+\cdots$. Find n.',p('','',7,('M1',r'$(4+nx)^2=16+8nx+n^2x^2$.'),('A1',r'$(1+x/4)^n=1+(n/4)x+\cdots$.'),('M1','Only constant-times-linear and linear-times-constant products contribute to x.'),('A1',r'The coefficient is $16(n/4)+8n$.'),('A1',r'$=12n$.'),('M1',r'$12n=96$.'),('A1',r'$n=8$.')))
add(188,'Relative finishing positions','Counting principles','A race has 12 distinct competitors, including Asha and Bella, with no ties.',p('a','Find the number of finishing orders in which Bella is immediately after Asha.',2,('M1','Treat ordered pair Asha–Bella as one block.'),('A1',f'$11!={math.factorial(11)}$.')),p('b','Find the number in which Bella is anywhere after Asha.',3,('R1','Swapping their names pairs every order with Bella first with one having Asha first.'),('M1','Exactly half of all 12! orders have the required order.'),('A1',f'$12!/2={math.factorial(12)//2}$.')))
add(189,'Multiplying two fractional binomial expansions','Binomial theorem',r'Use binomial expansions to show that $\sqrt{(1+2x)/(1-2x)}=1+2x+2x^2+O(x^3)$ for $|x|<1/2$.',p('','',8,('M1',r'Write the expression as $(1+2x)^{1/2}(1-2x)^{-1/2}$.'),('A1',r'$(1+2x)^{1/2}=1+x-\frac12x^2+O(x^3)$.'),('M1','Use the negative-half-power binomial expansion for the second factor.'),('A1',r'$(1-2x)^{-1/2}=1+x+\frac32x^2+O(x^3)$.'),('M1','Multiply and collect through degree 2.'),('A1',r'Linear coefficient is $1+1=2$.'),('A1',r'Quadratic coefficient is $-1/2+1+3/2=2$.'),('R1',r'Both require $|2x|<1$, proving the stated approximation and interval.')))
add(190,'A relation linking two sequence types','Proof and mathematical induction',r'Positive numbers a,b,c occur at positions m+1,n+1,k+1 of an arithmetic sequence with difference d, and also at those positions of a geometric sequence with positive first term and ratio.',p('a',r'Show that $b-c=(n-k)d$.',2,('M1',r'$b=A+nd$, $c=A+kd$.'),('A1',r'Subtraction gives $(n-k)d$.')),p('b',r'Show that $(b-c)m+(c-a)n+(a-b)k=0$.',2,('M1',r'Substitute the three difference expressions.'),('A1',r'$d[(n-k)m+(k-m)n+(m-n)k]=0$.')),p('c',r'Hence prove that $a^{2(b-c)}b^{2(c-a)}c^{2(a-b)}=1$.',4,('M1',r'Write $a=Vr^m,b=Vr^n,c=Vr^k$, with V,r>0.'),('A1',r'The product is $V^{2[(b-c)+(c-a)+(a-b)]}r^{2[(b-c)m+(c-a)n+(a-b)k]}$.'),('A1','Both exponents are zero, the second by part (b).'),('R1',r'The product is $V^0r^0=1$.')))
add(191,'Complex division and exact trigonometric values','Complex numbers',r'Let $z_1=4\operatorname{cis}(120^\circ)$ and $z_2=3+3i$.',p('a',r'Find $z_1/z_2$ in both modulus–argument and Cartesian forms.',7,('A1',r'$z_2=3\sqrt2\operatorname{cis}(45^\circ)$.'),('M1','Divide moduli and subtract arguments.'),('A1',r'$z_1/z_2=\frac4{3\sqrt2}\operatorname{cis}(75^\circ)$.'),('A1',r'$z_1=-2+2\sqrt3i$.'),('M1',r'Multiply $(-2+2\sqrt3i)/(3+3i)$ by $(3-3i)/(3-3i)$.'),('A1',r'Real part $=(\sqrt3-1)/3$.'),('A1',r'Imaginary part $=(\sqrt3+1)/3$.')),p('b',r'Hence find $\sin15^\circ\sin75^\circ\sin^245^\circ$ exactly.',5,('M1','Compare real and imaginary components in part (a).'),('A1',r'$\cos75^\circ=(\sqrt6-\sqrt2)/4$ and $\sin75^\circ=(\sqrt6+\sqrt2)/4$.'),('A1',r'$\sin15^\circ=\cos75^\circ$.'),('M1',r'The product is $[(6-2)/16]\times(1/2)$.'),('A1',r'$1/8$.')))
