add(192,'A digit-sum divisibility test','Proof and mathematical induction','Prove that a four-digit positive integer whose digit sum is divisible by 9 is itself divisible by 9.',p('','',5,('M1',r'Write the number as $N=1000a+100b+10c+d$.'),('A1',r'$N=999a+99b+9c+(a+b+c+d)$.'),('M1',r'Write $a+b+c+d=9k$ for an integer k.'),('A1',r'$N=9(111a+11b+c+k)$.'),('R1','The bracket is an integer, so 9 divides N.')))
add(193,'Counting cubics and identifying their roots','Complex numbers',r'A cubic $P(z)=az^3+bz^2+cz+d$ has coefficients from $\{3,6,12,24\}$.',p('a','Find the number of such polynomials if repetition is allowed, and then if all four coefficients must differ.',4,('M1','There are four independent choices for each of four coefficients.'),('A1',r'$4^4=256$.'),('M1','Without repetition, arrange the four coefficients.'),('A1',r'$4!=24$.')),p('b',r'Now all coefficients differ, $P(0)=24$, $(z+2)$ is a factor, and the other two roots are non-zero purely imaginary conjugates. Determine P.',7,('A1',r'$d=24$.'),('M1',r'Write the roots as $-2,it,-it$, where t is real and non-zero.'),('A1',r'The root sum gives $b=2a$.'),('M1',r'Factor as $a(z+2)(z^2+t^2)$, so $d=2c$.'),('A1',r'$c=12$.'),('A1',r'The remaining coefficients are $a=3,b=6$.'),('A1',r'$P(z)=3z^3+6z^2+12z+24$.')),p('c','Find all roots in Cartesian form and give their moduli and principal arguments.',7,('M1',r'$P(z)=3(z+2)(z^2+4)$.'),('A1',r'The roots are $-2,2i,-2i$.'),('A1','All have modulus 2.'),('A1',r'$\arg(-2)=\pi$.'),('A1',r'$\arg(2i)=\pi/2$.'),('A1',r'$\arg(-2i)=-\pi/2$.'),('R1','These three roots account for the cubic degree.')))
add(194,'An exponential inequality by induction','Proof and mathematical induction','Answer both parts.',p('a',r'Solve $x^2\ge2x+1$.',2,('M1',r'$x^2-2x-1\ge0$ has roots $1\pm\sqrt2$.'),('A1',r'$x\le1-\sqrt2$ or $x\ge1+\sqrt2$.')),p('b',r'Prove by induction that $2^n>n^2$ for every integer $n\ge5$.',6,('A1',r'At n=5, $32>25$.'),('M1',r'Assume $2^k>k^2$ for some integer $k\ge5$.'),('A1',r'$2^{k+1}>2k^2$.'),('M1',r'Part (a) gives $k^2\ge2k+1$ for $k\ge5$.'),('A1',r'Thus $2k^2\ge k^2+2k+1=(k+1)^2$.'),('R1','Therefore the strict inequality holds at k+1, completing induction.')))
add(195,'A trigonometric geometric series','Sequences and series',r'A geometric sequence has $u_1=24$ and $u_2=18\sin^2\theta$, where $0<\theta<2\pi$ and $\theta\ne\pi$.',p('a','Find its common ratio and prove that its infinite sum exists for every permitted angle.',5,('M1',r'$r=u_2/u_1$.'),('A1',r'$r=\frac34\sin^2\theta$.'),('A1',r'$0<\sin^2\theta\le1$ on the stated domain.'),('A1',r'$0<r\le3/4$.'),('R1',r'Hence $|r|<1$, which guarantees convergence.')),p('b',r'Show that $S_\infty=96/(5+3\cos2\theta)$.',4,('M1',r'$S_\infty=24/(1-\frac34\sin^2\theta)$.'),('M1',r'Use $\sin^2\theta=(1-\cos2\theta)/2$.'),('A1',r'The denominator becomes $(5+3\cos2\theta)/8$.'),('A1',r'$S_\infty=192/(5+3\cos2\theta)$.')) ,p('c','Find the maximum infinite sum and all angles where it occurs.',6,('M1','The numerator is positive, so minimize the positive denominator.'),('A1',r'The minimum denominator is $5-3=2$.'),('A1',r'Thus the maximum sum is $192/2=96$.'),('M1',r'This occurs when $\cos2\theta=-1$.'),('A1',r'$\theta=\pi/2$ or $3\pi/2$.'),('R1','Both angles belong to the permitted domain.')))
