add(197,'Parameters in a product of binomials','Binomial theorem',r'The expansion of $(1+x)^3(1+px)^4$ begins $1+qx+51x^2+\cdots$. Find all real pairs (p,q).',p('','',7,('A1',r'$(1+x)^3=1+3x+3x^2+\cdots$.'),('A1',r'$(1+px)^4=1+4px+6p^2x^2+\cdots$.'),('M1',r'$3+12p+6p^2=51$.'),('A1',r'$p^2+2p-8=(p+4)(p-2)=0$.'),('A1',r'$p=2$ or $-4$.'),('M1',r'$q=3+4p$.'),('A1',r'$(p,q)=(2,11)$ or $(-4,-13)$.')))
add(198,'A trigonometric product and approximation','Proof and mathematical induction',r'Let $F_n(x)=2^n\prod_{j=0}^{n-1}\cos(2^jx)$, where $\sin x\ne0$.',p('a',r'Prove by induction that $F_n(x)=\sin(2^nx)/\sin x$.',4,('A1',r'At n=1, $2\cos x=\sin2x/\sin x$.'),('M1','Assume the formula for n=k and multiply by $2\cos(2^kx)$.'),('A1',r'$F_{k+1}=2\sin(2^kx)\cos(2^kx)/\sin x=\sin(2^{k+1}x)/\sin x$.'),('R1','The base case and induction step establish the identity.')),p('b',r'Use Maclaurin expansions to approximate $\int_0^{1/20}\cos x\cos2x\cos4x\cos8x\,dx$, retaining terms through $x^2$ in the integrand.',12,('A1',r'$\sin16x=16x-(4096/6)x^3+O(x^5)$.'),('A1',r'$\sin x=x-x^3/6+O(x^5)$.'),('M1',r'Divide numerator and denominator by x.'),('A1',r'$1/(1-x^2/6+O(x^4))=1+x^2/6+O(x^4)$.'),('M1','Multiply the two truncated series.'),('A1',r'$\sin16x/\sin x=16-680x^2+O(x^4)$.'),('M1','Apply (a) at n=4 and divide by 16.'),('A1',r'The product is $1-\frac{85}{2}x^2+O(x^4)$.'),('M1','Integrate the quadratic approximation.'),('A1',r'Antiderivative $x-\frac{85}{6}x^3$.'),('A1',r'At $1/20$: $1/20-85/48000$.'),('A1',r'Approximation $463/9600$.')))
add(199,'A complex rational transformation','Complex numbers',r'For $z\ne-2i$, define $w=(z-2)/(z+2i)$.',p('a',r'When z=2i, express w in polar form and find $w^{12}$.',5,('M1',r'$w=(2i-2)/(4i)=(1+i)/2$.'),('A1',r'$|w|=1/\sqrt2$.'),('A1',r'$\arg w=\pi/4$.'),('M1',r'$w^{12}=2^{-6}\operatorname{cis}(3\pi)$.'),('A1',r'$w^{12}=-1/64$.')),p('b','Write w in Cartesian form when z=x+iy.',4,('M1',r'Multiply numerator and denominator by $x-i(y+2)$.'),('A1',r'The real numerator is $x^2-2x+y^2+2y$.'),('A1',r'The imaginary numerator is $2y-2x+4$.'),('A1',r'$w=\frac{x^2-2x+y^2+2y}{x^2+(y+2)^2}+i\frac{2y-2x+4}{x^2+(y+2)^2}$.')),p('c','Find the locus on which Re(w)=1.',2,('M1','Equate the real numerator to the denominator.'),('A1',r'$x+y=-2$, excluding $(0,-2)$.')),p('d','State the loci where w is real and where w is non-zero purely imaginary.',2,('A1',r'Real: $y=x-2$, excluding $(0,-2)$.'),('A1',r'Non-zero purely imaginary: $(x-1)^2+(y+1)^2=2$, excluding $(0,-2)$ and $(2,0)$.')),p('e',r'Given $\arg w=\pi/4$, find $|z|$.',2,('M1',r'Equate real and imaginary numerators: $x^2+y^2=4$ (with their common value positive).'),('A1',r'$|z|=2$.')))
add(200,'Allocations to adjacent cubicles','Counting principles','Eight labelled cubicles form two rows of four. Two cubicles are adjacent if they share a side. Six distinct people A, B, C, D, E and F are allocated cubicles.',p('a','If several people may share a cubicle, count allocations with D and E in different cubicles.',3,('M1','D has 8 choices and E then has 7.'),('A1',r'The other four people each have 8 independent choices.'),('A1',r'$8\cdot7\cdot8^4=7\cdot8^5=229376$.')),p('b','If each cubicle holds at most one person, count allocations where A and B occupy non-adjacent cubicles.',4,('A1','There are 6 horizontal and 4 vertical adjacent pairs.'),('M1',r'There are $8\cdot7-2(10)=36$ ordered non-adjacent choices for A,B.'),('M1',r'The other four people occupy distinct positions in $6\cdot5\cdot4\cdot3=360$ ways.'),('A1',r'$36\cdot360=12960$.')))
add(201,'A coefficient in a power of a quadratic','Binomial theorem',r'Consider $(2x^2+7x+3)^5$.',p('a','Factorize the quadratic.',2,('M1','Find factors whose product has leading coefficient 2 and constant 3.'),('A1',r'$2x^2+7x+3=(2x+1)(x+3)$.')),p('b',r'Find the coefficient of $x^9$ in the expansion.',5,('M1',r'Write $(2x+1)^5(x+3)^5$.'),('A1',r'The degree-5 and degree-4 coefficients of the first factor are 32 and 80.'),('A1',r'Those of the second factor are 1 and 15.'),('M1',r'For degree 9, add the degree-(5,4) and degree-(4,5) products.'),('A1',r'$32(15)+80(1)=560$.')))
