add(205,'A matching game with no fixed points','Counting principles','Six different cards are shuffled uniformly and placed beside six matching labels. A player wins if no card is beside its matching label. Independent repetitions use fresh shuffles.',p('a','Find the probability of a win.',6,('M1','Use inclusion–exclusion on events that a specified card is correctly placed.'),('A1',r'Total arrangements: $6!$.'),('A1',r'Derangements: $6!-\binom61 5!+\binom62 4!-\binom63 3!+\binom64 2!-\binom65 1!+1$.'),('M1','Evaluate this alternating sum.'),('A1',r'There are 265 winning arrangements.'),('A1',r'$P(\text{win})=265/720=53/144$.')),p('b','For 144 games, find the mean and variance of the number of wins.',5,('A1',r'$X\sim\mathrm{Bin}(144,53/144)$.'),('M1',r'$E(X)=np$.'),('A1',r'$E(X)=53$.'),('M1',r'$\mathrm{Var}(X)=np(1-p)$.'),('A1',r'$\mathrm{Var}(X)=4823/144\approx33.5$.')))
add(206,'Avoiding three consecutive letters','Counting principles','A code uses four distinct letters and nine distinct digits, each exactly once. Find the number of codes with no three consecutive letters.',p('','',6,('M1','Arrange the nine digits in $9!$ ways, creating ten gaps.'),('R1','Each gap may contain at most two letters.'),('A1',r'Four singly occupied gaps: $\binom{10}{4}$ selections.'),('A1',r'Occupancy 2,1,1: $10\binom92$; occupancy 2,2: $\binom{10}{2}$.'),('M1',r'For each selection, the four labelled letters fill the ordered slots in $4!$ ways.'),('A1',f'$9!4![\\binom{{10}}{{4}}+10\\binom92+\\binom{{10}}{{2}}]={math.factorial(9)*24*615}$.')))
add(207,'Induction for an exponential product','Proof and mathematical induction',r'Let $y=x^2e^{2x}$.',p('a','Find the first derivative.',1,('A1',r'$y\prime=(2x+2x^2)e^{2x}$.')),p('b',r'Prove that $y^{(n)}=2^{n-2}[4x^2+4nx+n(n-1)]e^{2x}$ for every integer $n\ge2$.',7,('A1',r'At n=2, direct differentiation gives $(4x^2+8x+2)e^{2x}$.'),('M1','Assume the expression at n=k.'),('M1','Differentiate using the product rule.'),('A1',r'$y^{(k+1)}=2^{k-2}[8x+4k+2(4x^2+4kx+k(k-1))]e^{2x}$.'),('A1',r'The bracket is $2[4x^2+4(k+1)x+k(k+1)]$.'),('A1',r'Thus $y^{(k+1)}=2^{k-1}[4x^2+4(k+1)x+k(k+1)]e^{2x}$.'),('R1','This is the required next case, proving the statement.')))
add(208,'Triple angles from complex powers','Complex numbers',r'Let $z=\cos\theta+i\sin\theta$.',p('a','Use de Moivre’s theorem to derive formulas for cos(3θ) and sin(3θ).',8,('M1',r'$z^3=\cos3\theta+i\sin3\theta$.'),('M1','Expand the cube algebraically.'),('A1',r'The real part is $\cos^3\theta-3\cos\theta\sin^2\theta$.'),('A1',r'The imaginary part is $3\cos^2\theta\sin\theta-\sin^3\theta$.'),('M1',r'Use $\sin^2\theta+\cos^2\theta=1$.'),('A1',r'$\cos3\theta=4\cos^3\theta-3\cos\theta$.'),('A1',r'$\sin3\theta=3\sin\theta-4\sin^3\theta$.'),('R1','Equality of complex numbers gives equality of their real and imaginary parts.')),p('b',r'Show that $(\sin3\theta-\sin\theta)/(\cos3\theta+\cos\theta)=\tan\theta$ for $-\pi/4<\theta<\pi/4$.',6,('M1','Substitute the identities from (a).'),('A1',r'The numerator is $2\sin\theta(1-2\sin^2\theta)$.'),('A1',r'The denominator is $2\cos\theta(2\cos^2\theta-1)$.'),('A1',r'Both bracketed factors equal $\cos2\theta$.'),('R1',r'On the interval, $\cos\theta$ and $\cos2\theta$ are non-zero.'),('A1',r'Cancellation leaves $\sin\theta/\cos\theta=\tan\theta$.')),p('c',r'Given $\sin\theta=1/4$ on that interval, find $\tan3\theta$ exactly.',5,('A1',r'$\cos\theta=\sqrt{15}/4$.'),('A1',r'$\sin3\theta=3/4-4/64=11/16$.'),('M1',r'$\cos3\theta=4(\sqrt{15}/4)^3-3\sqrt{15}/4$.'),('A1',r'$\cos3\theta=3\sqrt{15}/16$.'),('A1',r'$\tan3\theta=11\sqrt{15}/45$.')))
