add(210,'Bounding a sum of reciprocal square roots','Proof and mathematical induction','Answer each part for positive integer indices.',p('a',r'Prove $1/[2\sqrt{n+1}]<\sqrt{n+1}-\sqrt n$ for $n\ge1$.',3,('M1',r'Rationalize: $\sqrt{n+1}-\sqrt n=1/(\sqrt{n+1}+\sqrt n)$.'),('A1',r'$\sqrt{n+1}+\sqrt n<2\sqrt{n+1}$.'),('R1','All terms are positive, so taking reciprocals reverses the inequality.')),p('b',r'Verify $1/\sqrt3<2\sqrt3-2\sqrt2$.',2,('M1','Use (a) with n=2.'),('A1','Multiply the strict inequality by 2.')),p('c',r'Prove by induction that $\sum_{r=3}^{n}1/\sqrt r<2\sqrt n-2\sqrt2$ for every integer $n\ge3$.',9,('A1','The n=3 case is part (b).'),('M1',r'Assume $S_k<2\sqrt k-2\sqrt2$ for some $k\ge3$.'),('A1',r'$S_{k+1}=S_k+1/\sqrt{k+1}$.'),('M1','Apply the induction hypothesis.'),('A1',r'$S_{k+1}<2\sqrt k-2\sqrt2+1/\sqrt{k+1}$.'),('M1','Use (a) at n=k and multiply by 2.'),('A1',r'$1/\sqrt{k+1}<2\sqrt{k+1}-2\sqrt k$.'),('A1',r'Thus $S_{k+1}<2\sqrt{k+1}-2\sqrt2$.'),('R1','This is the next case, so induction proves the inequality.')))
add(211,'Repeated derivatives and a quotient series','Proof and mathematical induction',r'Let $f(x)=(3x+1)e^{3x}$ and $h(x)=\cos(kx)/f(x)$.',p('a',r'Find $f\prime(x)$.',2,('M1','Use the product rule.'),('A1',r'$f\prime=(9x+6)e^{3x}$.')),p('b',r'Prove $f^{(n)}(x)=3^n(3x+n+1)e^{3x}$ for every positive integer n.',6,('A1','The n=1 case follows from (a).'),('M1','Assume the formula for n=j.'),('M1','Differentiate the assumed expression.'),('A1',r'$f^{(j+1)}=3^j[3+3(3x+j+1)]e^{3x}$.'),('A1',r'$=3^{j+1}(3x+j+2)e^{3x}$.'),('R1','This is the required next case, completing induction.')),p('c',r'Find all real k for which the Maclaurin expansion of h has no $x^2$ term.',6,('A1',r'$(1+3x)^{-1}=1-3x+9x^2+O(x^3)$.'),('A1',r'$e^{-3x}=1-3x+\frac92x^2+O(x^3)$.'),('M1','Multiply to obtain $1/f(x)$.'),('A1',r'$1/f(x)=1-6x+\frac{45}{2}x^2+O(x^3)$.'),('M1',r'Multiply by $\cos(kx)=1-k^2x^2/2+O(x^4)$, giving $45/2-k^2/2=0$.'),('A1',r'$k=\pm3\sqrt5$.')))
add(212,'Fourth roots and an exact half-angle value','Complex numbers',r'Consider $z^4=16i$.',p('a',r'Use de Moivre’s theorem to derive $\cos4\theta=8\cos^4\theta-8\cos^2\theta+1$.',6,('M1',r'Expand $(\cos\theta+i\sin\theta)^4$.'),('A1',r'The real part is $\cos^4\theta-6\cos^2\theta\sin^2\theta+\sin^4\theta$.'),('M1',r'Substitute $\sin^2\theta=1-\cos^2\theta$.'),('A1',r'$\cos^4\theta-6\cos^2\theta(1-\cos^2\theta)+(1-\cos^2\theta)^2$.'),('A1',r'$=8\cos^4\theta-8\cos^2\theta+1$.'),('R1','By de Moivre, this real part equals cos(4θ).')),p('b','Give the root with the smallest positive argument in polar form.',4,('A1',r'$16i=16\operatorname{cis}(\pi/2)$.'),('M1','Take fourth roots.'),('A1',r'Root modulus is 2, with arguments $\pi/8+k\pi/2$.'),('A1',r'The required root is $2\operatorname{cis}(\pi/8)$.')),p('c',r'Show that $u=\cos(\pi/8)$ satisfies $8u^4-8u^2+1=0$.',4,('M1','Use the identity in (a) at θ=π/8.'),('A1',r'$4\theta=\pi/2$.'),('A1',r'$\cos4\theta=0$.'),('A1',r'Thus $8u^4-8u^2+1=0$.')),p('d',r'Hence find $\cos(\pi/8)$ exactly.',5,('M1',r'Let $v=u^2$ and solve $8v^2-8v+1=0$.'),('A1',r'$v=(2\pm\sqrt2)/4$.'),('R1',r'$0<\pi/8<\pi/4$ implies $u^2>1/2$, choosing the plus sign.'),('M1','Take the positive square root because the angle is acute.'),('A1',r'$\cos(\pi/8)=\sqrt{2+\sqrt2}/2$.')))
add(213,'Angle equations and fourth roots','Complex numbers','Angles in (a),(b) are in degrees; angles in (c) are in radians.',p('a',r'Solve $2\sin(x+150^\circ)=\sqrt3\cos(x+30^\circ)$ for $0\le x\le180^\circ$.',5,('M1','Expand both compound angles.'),('A1',r'$-\sqrt3\sin x+\cos x=\frac32\cos x-\frac{\sqrt3}{2}\sin x$.'),('A1',r'$\sqrt3\sin x+\cos x=0$.'),('M1',r'$\tan x=-1/\sqrt3$; cos x=0 is not a solution.'),('A1',r'$x=150^\circ$.')),p('b',r'Find $\sin105^\circ+\cos105^\circ$ exactly.',3,('M1',r'$\sin t+\cos t=\sqrt2\sin(t+45^\circ)$.'),('A1',r'At $t=105^\circ$, this is $\sqrt2\sin150^\circ$.'),('A1',r'$\sqrt2/2$.')),p('c',r'Let $z=\sin6\theta+i(1-\cos6\theta)$, where $0<\theta<\pi/6$. Find its modulus and principal argument, and all its fourth roots in polar form.',14,('M1',r'Use $\sin6\theta=2\sin3\theta\cos3\theta$.'),('A1',r'$1-\cos6\theta=2\sin^23\theta$.'),('M1',r'Factor out $2\sin3\theta$.'),('A1',r'$z=2\sin3\theta(\cos3\theta+i\sin3\theta)$.'),('R1',r'$0<3\theta<\pi/2$, so $2\sin3\theta>0$.'),('A1',r'$|z|=2\sin3\theta$.'),('A1',r'$\arg z=3\theta$.'),('M1',r'Write a fourth root as $\rho\operatorname{cis}\phi$.'),('A1',r'$\rho^4=2\sin3\theta$.'),('A1',r'$\rho=(2\sin3\theta)^{1/4}$.'),('M1',r'$4\phi=3\theta+2k\pi$.'),('A1',r'$\phi=3\theta/4+k\pi/2$.'),('A1',r'The four roots are $(2\sin3\theta)^{1/4}\operatorname{cis}(3\theta/4+k\pi/2)$, k=0,1,2,3.'),('R1','These four distinct arguments modulo 2π give all roots.')))
add(214,'Summing three roots in a quadrant','Complex numbers',r'Consider the equation $z^{16}=65536$. Let S be the sum of its roots strictly inside the first quadrant.',p('a','Find those roots in polar form.',5,('M1',r'$65536=2^{16}$, so every root has modulus 2.'),('A1',r'Arguments are $k\pi/8$, k=0,...,15.'),('R1','Strict first-quadrant arguments have k=1,2,3.'),('A1',r'$2\operatorname{cis}(\pi/8)$ and $2\operatorname{cis}(\pi/4)$.'),('A1',r'$2\operatorname{cis}(3\pi/8)$.')),p('b','Find S exactly in Cartesian form.',11,('M1','Add real and imaginary parts separately.'),('A1',r'Real part $=2(\cos\frac\pi8+\cos\frac\pi4+\cos\frac{3\pi}8)$.'),('A1',r'Imaginary part $=2(\sin\frac\pi8+\sin\frac\pi4+\sin\frac{3\pi}8)$.'),('R1','Complementary-angle identities show these two sums are equal.'),('M1','Use the half-angle formulas with positive square roots.'),('A1',r'$\cos(\pi/8)=\sqrt{2+\sqrt2}/2$.'),('A1',r'$\sin(\pi/8)=\sqrt{2-\sqrt2}/2$.'),('A1',r'$\cos(3\pi/8)=\sin(\pi/8)$.'),('A1',r'$\sin(3\pi/8)=\cos(\pi/8)$.'),('A1',r'$2\cos(\pi/4)=\sqrt2$.'),('A1',r'$S=(\sqrt{2+\sqrt2}+\sqrt2+\sqrt{2-\sqrt2})(1+i)$.')))
add(215,'Roots, products and rational powers','Complex numbers','Use exact values throughout.',p('a',r'Solve $z^3=64$ in Cartesian form.',6,('M1',r'$64=64\operatorname{cis}(2k\pi)$.'),('A1','Root modulus is 4.'),('M1',r'Arguments are $2k\pi/3$, k=0,1,2.'),('A1',r'$z=4$.'),('A1',r'$z=-2+2\sqrt3i$.'),('A1',r'$z=-2-2\sqrt3i$.')),p('b',r'Let $z_1=-2+2i$ and $z_2=\frac13\operatorname{cis}(\pi/3)$. Find their product in polar and Cartesian forms; hence find $\tan(\pi/12)$. For rational p define $(z_1z_2)^p=(2\sqrt2/3)^p\operatorname{cis}(13p\pi/12)$. Find the least positive p making this power positive real.',11,('A1',r'$z_1=2\sqrt2\operatorname{cis}(3\pi/4)$.'),('M1','Multiply moduli and add arguments.'),('A1',r'$z_1z_2=(2\sqrt2/3)\operatorname{cis}(13\pi/12)$.'),('M1',r'Alternatively multiply $(-2+2i)(1/6+i\sqrt3/6)$.'),('A1',r'$z_1z_2=-(1+\sqrt3)/3+i(1-\sqrt3)/3$.'),('M1','The tangent is imaginary part divided by real part.'),('A1',r'$\tan(\pi/12)=\tan(13\pi/12)=(\sqrt3-1)/(\sqrt3+1)$.'),('A1',r'$=2-\sqrt3$.'),('M1',r'Positive real requires $13p\pi/12=2m\pi$.'),('A1',r'$p=24m/13$ for an integer m.'),('A1',r'The least positive value is $p=24/13$.')) ,note='The source asks about noninteger complex powers without specifying a branch. The variant explicitly defines the chosen argument for powers, removing that ambiguity; product and cube roots were recalculated.')
