add(216,'Saving to repay a loan and funding a perpetuity','Financial and growth models','A loan of USD 120000 accrues interest at 5.2% annually and is repaid in a single payment after 8 years. A separate savings account pays 4% nominal annually, compounded quarterly. All monetary answers should be given to the nearest cent.',p('a','Find the loan repayment.',3,('M1',r'$L=120000(1.052)^8$.'),('A1','There are eight annual compounding periods.'),('A1',f'USD {D(loan)}.')),p('b','Write the value of 32 equal quarter-end deposits of P dollars at the end of 8 years.',3,('A1',r'The quarterly multiplier is 1.01.'),('M1',r'Value $=P(1+1.01+\cdots+1.01^{31})$.'),('A1',r'$P(1.01^{32}-1)/0.01$.')),p('c','Find the quarterly deposit needed to meet the loan repayment.',3,('M1','Equate the savings value to the unrounded loan repayment.'),('A1',r'$P=120000(1.052)^8(0.01)/(1.01^{32}-1)$.'),('A1',f'USD {D(quarter)}.')),p('d','A fund must also provide USD 9000 at every year-end forever, earning 4.5% effective annually. Find its required initial value.',6,('M1','Discount each withdrawal to the starting date.'),('A1',r'Initial value $=9000/1.045+9000/1.045^2+\cdots$.'),('A1',r'This is geometric with first term $9000/1.045$ and ratio $1/1.045$.'),('R1','The ratio is less than 1, so the series converges.'),('M1',r'Sum $=(9000/1.045)/(1-1/1.045)=9000/0.045$.'),('A1','USD 200000.00.')))
add(217,'An argument independent of a parameter','Complex numbers',r'Let $z_1=-1+2ai$ and $z_2=(2a-1)/(2a+1)+i$, where a is real and $a\ne-1/2$. Find every possible principal value of $\arg(z_2/z_1)$.',p('','',7,('M1',r'Observe $(1-i)(-1+2ai)=(2a-1)+(2a+1)i$.'),('A1',r'$z_2=(1-i)z_1/(2a+1)$.'),('R1',r'$z_1\ne0$, since its real part is -1.'),('A1',r'$z_2/z_1=(1-i)/(2a+1)$.'),('M1','Separate the cases according to the sign of 2a+1.'),('A1',r'For $a>-1/2$, the principal argument is $-\pi/4$.'),('A1',r'For $a<-1/2$, the principal argument is $3\pi/4$.')))
add(218,'Intersections of three parameterized planes','Systems of equations',r'The planes are $$-2x+ay+4z=4,\quad x+by-2z=-2,\quad 2x-y+cz=1.$$ ',p('a','Find all conditions on a,b,c for infinitely many common points.',7,('M1','Add twice the second equation to the first.'),('A1',r'$(a+2b)y=0$.'),('M1','Subtract twice the second equation from the third.'),('A1',r'$-(1+2b)y+(c+4)z=5$.'),('R1',r'If $a+2b\ne0$, y=0 and there is either one solution or none.'),('R1',r'If $a+2b=0$, the last relation has infinitely many pairs (y,z) unless both coefficients vanish.'),('A1',r'Infinitely many solutions exactly when $a=-2b$ and $(b,c)\ne(-1/2,-4)$.')),p('b','Describe the geometry when there are infinitely many common points.',2,('A1','The first two planes coincide.'),('A1','The third plane cuts them in a common line; all three cannot coincide because the reduced right side is 5.')),p('c','State the conditions for no common point.',2,('M1','Inconsistency requires c=-4 in the reduced equations.'),('A1',r'$c=-4$ and either $a+2b\ne0$ or $b=-1/2$.')))
add(219,'Cubic roots in arithmetic or geometric progression','Complex numbers',r'A monic cubic is $P(z)=z^3-12z^2+36z+d$, with roots $\alpha,\beta,\gamma$.',p('a','State the sum, pairwise product sum and product of its roots.',3,('A1',r'$\alpha+\beta+\gamma=12$.'),('A1',r'$\alpha\beta+\beta\gamma+\gamma\alpha=36$.'),('A1',r'$\alpha\beta\gamma=-d$.')),p('b','Find d if the three roots form an arithmetic progression.',5,('M1',r'Write the roots $a-t,a,a+t$.'),('A1',r'$3a=12$, so a=4.'),('M1',r'The pairwise sum is $3a^2-t^2=36$.'),('A1',r'$t^2=12$.'),('A1',r'$-d=a(a^2-t^2)=4(16-12)=16$, so $d=-16$.')),p('c','Find d if the roots form a geometric progression.',6,('M1',r'Write the non-zero roots $a/r,a,ar$.'),('A1',r'$a(r^{-1}+1+r)=12$.'),('A1',r'$a^2(r^{-1}+1+r)=36$.'),('M1','Divide the second equation by the first.'),('A1',r'$a=3$; the root product is $a^3=27$.'),('A1',r'$d=-27$.')))
add(220,'Complex powers and a trigonometric equation','Complex numbers',r'Let $w=\cos\alpha+i\sin\alpha$.',p('a',r'Evaluate $(\cos(\pi/4)+i\sin(\pi/4))^8$.',2,('M1',r'By de Moivre this is $\operatorname{cis}(2\pi)$.'),('A1','1.')),p('b',r'Prove by induction that $(w^*)^n=(w^n)^*$ for all positive integers n.',6,('A1','The n=1 case is immediate.'),('M1','Assume the result for n=k.'),('M1',r'$(w^*)^{k+1}=(w^*)^kw^*$.'),('A1',r'$=(w^k)^*w^*$ by the hypothesis.'),('A1',r'$=(w^kw)^*=(w^{k+1})^*$, using conjugation of products.'),('R1','This proves the next case and the statement.')),p('c',r'Show $w^n-(w^*)^n=2i\sin(n\alpha)$.',2,('M1','Apply de Moivre to w and its conjugate.'),('A1',r'Subtract $(\cos n\alpha+i\sin n\alpha)-(\cos n\alpha-i\sin n\alpha)$.')),p('d',r'Use complex powers to derive $\sin3\alpha=3\sin\alpha-4\sin^3\alpha$.',5,('M1','Expand $w^3$.'),('A1',r'Its imaginary part is $3\cos^2\alpha\sin\alpha-\sin^3\alpha$.'),('M1',r'Substitute $\cos^2\alpha=1-\sin^2\alpha$.'),('A1',r'This simplifies to $3\sin\alpha-4\sin^3\alpha$.'),('R1','By de Moivre the imaginary part equals sin(3α).')),p('e',r'Solve $4\sin^3\alpha-(2\cos\alpha+3)\sin\alpha=0$ for $0\le\alpha\le\pi$.',6,('M1','Use (d) and the double-angle formula.'),('A1',r'The equation becomes $\sin3\alpha+\sin2\alpha=0$.'),('M1',r'$2\sin(5\alpha/2)\cos(\alpha/2)=0$.'),('A1',r'$\sin(5\alpha/2)=0$ gives $\alpha=0,2\pi/5,4\pi/5$ in the interval.'),('A1',r'$\cos(\alpha/2)=0$ gives $\alpha=\pi$.'),('R1','These four values exhaust both factors and include the endpoints.')))
