add(223,'Trigonometric equations and complex roots','Complex numbers','Use degrees for (a),(b) and radians for (c).',p('a',r'Solve $\sin(x+90^\circ)=\sqrt2\cos(x-45^\circ)$ for $0<x<360^\circ$.',5,('A1',r'The left side is $\cos x$.'),('M1','Expand the compound angle on the right.'),('A1',r'The right side is $\cos x+\sin x$.'),('A1',r'Thus $\sin x=0$.'),('A1',r'$x=180^\circ$; endpoints are excluded.')),p('b',r'Find $\sin75^\circ-\cos75^\circ$ exactly.',4,('M1',r'Write $75^\circ=45^\circ+30^\circ$.'),('A1',r'$\sin75^\circ=(\sqrt6+\sqrt2)/4$.'),('A1',r'$\cos75^\circ=(\sqrt6-\sqrt2)/4$.'),('A1',r'The difference is $\sqrt2/2$.')),p('c',r'Let $z=1-\cos6\theta-i\sin6\theta$, where $0<\theta<\pi/3$. Find its modulus, principal argument and all fourth roots.',11,('M1','Use the double-angle formulas.'),('A1',r'$z=2\sin^23\theta-2i\sin3\theta\cos3\theta$.'),('M1',r'Factor: $z=2\sin3\theta(\sin3\theta-i\cos3\theta)$.'),('R1',r'$0<3\theta<\pi$, so $\sin3\theta>0$.'),('A1',r'$|z|=2\sin3\theta$.'),('A1',r'$\sin3\theta-i\cos3\theta=\operatorname{cis}(3\theta-\pi/2)$.'),('A1',r'$\arg z=3\theta-\pi/2\in(-\pi/2,\pi/2)$.'),('M1','Take fourth roots of the modulus.'),('A1',r'Root modulus $(2\sin3\theta)^{1/4}$.'),('M1','Divide arguments, including full rotations, by 4.'),('A1',r'Roots $(2\sin3\theta)^{1/4}\operatorname{cis}((3\theta-\pi/2)/4+k\pi/2)$, k=0,1,2,3.')))
