add(227,'Waiting for four successes','Counting principles','Each independent purchase includes a special token with probability 1/4. Let X be the purchase number on which the fourth token is obtained.',p('a','Find P(X=4) and P(X=5).',4,('M1','Four immediate successes are required for X=4.'),('A1',r'$P(X=4)=(1/4)^4=1/256$.'),('M1','For X=5, the first four contain three successes, and the fifth succeeds.'),('A1',r'$P(X=5)=\binom43(1/4)^4(3/4)=3/256$.')),p('b',r'Show that $P(X=n)=\frac1{1536}(n-1)(n^2+an+b)(3/4)^{n-4}$ for $n\ge4$, finding a and b.',5,('M1','The first n-1 purchases contain exactly three successes and purchase n succeeds.'),('A1',r'$P(X=n)=\binom{n-1}3(1/4)^4(3/4)^{n-4}$.'),('M1',r'Expand $\binom{n-1}3=(n-1)(n-2)(n-3)/6$.'),('A1',r'$(n-2)(n-3)=n^2-5n+6$ and $6(4^4)=1536$.'),('A1',r'$a=-5,b=6$.')),p('c',r'Find $P(X=n)/P(X=n-1)$ for $n\ge5$.',3,('M1','Divide the two binomial mass formulas.'),('A1',r'Cancel common factors to obtain $(3/4)(n-1)/(n-4)$.'),('A1',r'$3(n-1)/[4(n-4)]$.')),p('d','Find all most likely values of X.',4,('M1','Compare the ratio in (c) with 1.'),('A1',r'It exceeds 1 for n<13 and equals 1 for n=13.'),('A1','It is less than 1 for n>13.'),('A1','The two modes are 12 and 13.')),p('e','Find the least N for which the probability of obtaining at least four tokens in N purchases exceeds 1/2.',4,('M1',r'Use $Y\sim\mathrm{Bin}(N,1/4)$ and $P(Y\ge4)>1/2$.'),('A1',r'$P(Y\ge4)=1-\sum_{j=0}^3\binom Nj(1/4)^j(3/4)^{N-j}$.'),('A1',f'For N={N-1}, probability is {binom.sf(3,N-1,.25):.6f}; for N={N}, it is {binom.sf(3,N,.25):.6f}.'),('A1',f'The least value is N={N}.')))
add(228,'Repeated derivatives and a Maclaurin coefficient','Proof and mathematical induction',r'Let $f(x)=(1-2x)^{-1/2}$ for $x<1/2$.',p('a','Find the second derivative.',3,('M1','Use the chain rule.'),('A1',r'$f\prime=(1-2x)^{-3/2}$.'),('A1',r'$f\prime\prime=3(1-2x)^{-5/2}$.')),p('b',r'Prove that $f^{(n)}(x)=\frac{(2n)!}{2^n n!}(1-2x)^{-n-1/2}$ for every positive integer n.',9,('A1',r'For n=1, the coefficient is $2!/(2\cdot1!)=1$, agreeing with (a).'),('M1','Assume the formula at n=k.'),('M1','Differentiate the assumed expression.'),('A1',r'The chain-rule factor is $2(k+1/2)=2k+1$.'),('A1',r'$f^{(k+1)}=\frac{(2k)!(2k+1)}{2^kk!}(1-2x)^{-k-3/2}$.'),('M1','Multiply the coefficient numerator and denominator by 2k+2.'),('A1',r'$\frac{(2k+2)!}{2^kk!(2k+2)}=\frac{(2k+2)!}{2^{k+1}(k+1)!}$.'),('A1',r'The exponent is $-(k+1)-1/2$.'),('R1','Thus the next case holds, completing induction.')),p('c',r'Find all real m such that the coefficient of $x^2$ in $f(x)\cos(mx)$ is $-1/2$.',9,('A1',r'$f(0)=1$.'),('A1',r'$f\prime(0)=1$.'),('A1',r'$f\prime\prime(0)=3$.'),('M1','Use the Maclaurin formula.'),('A1',r'$f(x)=1+x+\frac32x^2+O(x^3)$.'),('A1',r'$\cos(mx)=1-\frac{m^2}2x^2+O(x^4)$.'),('M1','Multiply and collect degree 2.'),('A1',r'$3/2-m^2/2=-1/2$, so $m^2=4$.'),('A1',r'$m=2$ or $m=-2$.')))
add(229,'Arctangent transformations and a telescoping sum','Proof and mathematical induction','The inverse tangent takes its principal values in $(-\pi/2,\pi/2)$.',p('a',r'Describe the transformations taking $y=\arctan x$ to $y=\arctan(3x-2)+\pi/2$, and give the horizontal asymptotes.',3,('A1','Compress horizontally by factor 1/3, then translate right by 2/3.'),('A1',r'Translate upwards by $\pi/2$.'),('A1',r'The horizontal asymptotes are y=0 and $y=\pi$.')),p('b',r'Prove $\arctan p-\arctan q=\arctan((p-q)/(1+pq))$ for positive p,q.',3,('M1',r'Let $A=\arctan p$, $B=\arctan q$ and apply the tangent subtraction formula.'),('A1',r'$\tan(A-B)=(p-q)/(1+pq)$.'),('R1',r'Since A,B are in $(0,\pi/2)$, their difference is in the principal arctangent interval, so inversion is valid.')),p('c',r'Hence show that $\arctan(x+3)-\arctan(x+2)=\arctan(1/(x^2+5x+7))$ for $x\ge0$.',3,('M1','Apply (b) to p=x+3 and q=x+2, both positive.'),('A1',r'$p-q=1$ and $1+pq=x^2+5x+7$.'),('A1','Substitution gives the stated identity.')),p('d',r'Prove by induction that $\sum_{r=1}^n\arctan(1/(r^2+5r+7))=\arctan(n+3)-\arctan3$ for positive integers n.',8,('A1','At n=1, (c) gives arctan(1/13)=arctan4−arctan3.'),('M1','Assume the sum formula for n=k.'),('M1','Add the term with r=k+1.'),('A1',r'This term is $\arctan(k+4)-\arctan(k+3)$ by (c).'),('M1','Insert the assumed expression for the first k terms.'),('A1',r'$S_{k+1}=\arctan(k+3)-\arctan3+\arctan(k+4)-\arctan(k+3)$.'),('A1',r'$=\arctan(k+4)-\arctan3$.'),('R1','This is the claimed next case, so the statement follows by induction.')) ,note='The source inverse-tangent subtraction statement needs a branch restriction. Positive p,q and x≥0 are explicitly imposed; the telescoping identity is then valid at every positive integer index.')
